def solve_S(F, max_k):
    S = {F}
    for k in range(1, max_k + 1):
        new_S = set(S)
        # S_k = S_{k-1} \cup {x | exists y s.t. {y-1, y+1} \subseteq S_{k-1} \cup {F}}
        # This is equivalent to:
        # S_k = S_{k-1} \cup {x | exists y s.t. (y-1 in S_{k-1} or y-1 == F) and (y+1 in S_{k-1} or y+1 == F)}

        # First, find all "good" y's.
        # A y is "good" if {y-1, y+1} \subseteq S \cup {F}
        good_y = []
        # What is the range of y? 
        # Since F is up to 100, let's say y up to 200.
        for y in range(2, 201):
            if (y-1 in S or y-1 == F) and (y+1 in S or y+1 == F):
                good_y.append(y)

        if not good_y:
            break

        for y in good_y:
            # For each good y, all its multiples and divisors (except 1) are in new_S
            # Multiples
            for x in range(y, 201, y):
                new_S.add(x)
            # Divisors
            for d in range(2, y + 1):
                if y % d == 0:
                    new_S.add(d)

        if new_S == S:
            break
        S = new_S
    return S

for F in range(2, 10):
    print(f"F={F}, S_max={solve_S(F, 50)}")
